Configured a dummy users class and a dummy wildcard auth block.

```nix
{
  hackint = {
    solanum = {
      enable = true;
      isHub = lib.mkDefault false;
      exempts = [
        # TODO: add monitoring
      ];
      opers = {
      };
      classes = {
        server = {
          pingTime = "5 minutes";
          autoconnFreq = "1 minute";
          maxConnections = 16;
          maxAutoconn = if config.hackint.solanum.isHub then 0 else 1;
          sendQ = "2 megabytes";
        };
        users = {
          maxConnections = 128;
          sendQ = "100 kbytes";
        };
      };
      auth = [ {
        hostmasks = [
          "*@*"
        ];
        class = "users";
      } ];
    };
  };
}
```

results in

```
class "users" {
  max_number = 16384;
  ping_time = 2 minutes;
  sendq = 100 kbytes;
};

auth {
  user = "*@*";
  class = "users";
};
```

